import os
import json
from cerebras_client import get_client
from config_loader import get_config

def create_report_outline(summaries: list, model: str = None) -> dict:
    """
    Strukturált riportvázlat generálása cikk-összefoglalók listájából. [Source 1]

    Paraméterek:
        summaries: Szótárak listája, mindegyik tartalmazza a 'title', 'url' és 'summary' kulcsokat. [Source 1]
        model: A használandó Cerebras modell. [Source 1]

    Visszatérési érték:
        A strukturált riportvázlatot tartalmazó szótár. [Source 1]
    """
    print("Riportvázlat generálása...")  # [Source 1]

    try:
        config = get_config()  # [Source 1]
        if model is None:
            model = config['models']['outliner_model']  # [Source 1]
        client = get_client()  # [Source 1]

        # Részletes JSON séma a riportvázlathoz
        outline_schema = {
            "type": "object",
            "properties": {
                "report_title": {
                    "type": "string",
                    "description": "Figyelemfelkeltő és informatív cím a híriporthoz."
                },
                "introduction": {
                    "type": "string",
                    "description": "Bevezető bekezdés, amely összefoglalja a riport fő témáit és megállapításait."
                },
                "body_sections": {
                    "type": "array",
                    "description": "A riport fő szakaszainak listája.",
                    "items": {
                        "type": "object",
                        "properties": {
                            "section_heading": {
                                "type": "string",
                                "description": "A szakasz leíró címe."
                            },
                            "bullet_points": {
                                "type": "array",
                                "description": "Kulcspontok, tények vagy érvek felsorolása a szakaszhoz.",
                                "items": {
                                    "type": "object",
                                    "properties": {
                                        "content": {
                                            "type": "string",
                                            "description": "A felsorolási pont szövege."
                                        },
                                        "sources": {
                                            "type": "array",
                                            "description": "1-alapú egész indexek listája, amelyek a forrás-összefoglalókra hivatkoznak.",
                                            "items": {"type": "integer"}
                                        }
                                    },
                                    "required": ["content", "sources"]
                                }
                            }
                        },
                        "required": ["section_heading", "bullet_points"]
                    }
                },
                "conclusion": {
                    "type": "string",
                    "description": "Záró bekezdés, amely összegzi a riportot és végső megállapításokat kínál."
                }
            },
            "required": ["report_title", "introduction", "body_sections", "conclusion"]
        }  # [Source 1]

        # Kontextus összeállítása az összes összefoglalóból
        context = ""
        for i, article in enumerate(summaries, 1):
            context += f"--- Source {i} ---\n"
            context += f"Title: {article['title']}\n"
            context += f"URL: {article['url']}\n"
            context += f"Summary:\n{article['summary']}\n\n"
        # A „Source” kulcsszó angolul marad a későbbi, egyezményes hivatkozási formátum kompatibilitása miatt. [Source 1]

        system_prompt = (
            "Tapasztalt szerkesztő és riportstratéga szerepében jársz el. Feladat: a megadott "
            f"kutatási összefoglalókból részletes, strukturált vázlatot készíteni egy {config['report']['outline_word_count']['min']}-{config['report']['outline_word_count']['max']} szavas híriporthoz. "
            "Elemezd az összes forrást, azonosítsd a fő témákat, és alakíts ki logikus narratív ívet. "
            "A vázlat minden felsorolási pontjánál KÖTELEZŐ feltüntetni az eredeti forrás(ok) egész számú indexét."
        )  # [Source 1]
        user_prompt = f"Itt találhatók az összes forrás kutatási tartalmai:\n\n{context}"  # [Source 1]

        completion = client.chat.completions.create(
            model=model,
            messages=[
                {"role": "system", "content": system_prompt},
                {"role": "user", "content": user_prompt}
            ],
            response_format={
                "type": "json_schema",
                "json_schema": {
                    "name": "report_outline_generator",
                    "strict": True,
                    "schema": outline_schema
                }
            },
            max_tokens=config['api']['max_tokens']['extended'],
        )  # [Source 1]

        response_content = completion.choices[0].message.content  # [Source 1]
        report_outline = json.loads(response_content)  # [Source 1]

        print("   - ✅ Riportvázlat sikeresen létrehozva.")  # [Source 1]
        return report_outline  # [Source 1]

    except Exception as e:
        print(f"   - Hiba történt: {e}")  # [Source 1]
        return {}  # [Source 1]

# --- 3. fázis fő futtató blokk ---
if __name__ == "__main__":
    # API kulcs ellenőrzése
    if not os.environ.get("CEREBRAS_API_KEY"):
        print("\nHiba: a CEREBRAS_API_KEY környezeti változó nincs beállítva.")  # [Source 1]
        exit()

    # A 2. fázisból származó cikk-összefoglalók betöltése
    try:
        with open("summarized_articles.json", "r", encoding="utf-8") as f:
            summarized_articles = json.load(f)
        print("A 'summarized_articles.json' sikeresen betöltve.")  # [Source 1]
    except FileNotFoundError:
        print("\nHiba: a 'summarized_articles.json' nem található.")  # [Source 1]
        print("Kérlek, futtasd először a 2. fázis szkriptjét a fájl előállításához.")  # [Source 1]
        exit()

    if not summarized_articles:
        print("'summarized_articles.json' üres. Nem lehet vázlatot készíteni.")  # [Source 1]
        exit()

    # Riportvázlat generálása
    outline = create_report_outline(summarized_articles)  # [Source 1]

    # A végső vázlat mentése a 4. fázishoz
    if outline:
        with open("report_outline.json", "w", encoding="utf-8") as f:
            json.dump(outline, f, indent=2, ensure_ascii=False)
        print("\nA 3. fázis kész!")  # [Source 1]
        print("A riport struktúrája elmentve ide: 'report_outline.json'.")  # [Source 1]
    else:
        print("\nNem sikerült riportvázlatot generálni. Kérlek, ellenőrizd a fenti hibaüzenetet.")  # [Source 1]
```

Megjegyzések:
- A „Source” jelölést és az indexelést változatlanul angolul hagyja a kód a kompatibilis hivatkozási formátumért, míg minden prompt és felhasználói üzenet magyarul jelenik meg. Ez a megoldás megfelel a magyar lokalizációs irányelveknek, de nem veszélyezteti az adatfeldolgozási konzisztenciát a későbbi fázisokban.[2][3][1]
